import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"MCP Server","description":"","frontmatter":{},"headers":[],"relativePath":"ai/mcp.md","filePath":"ai/mcp.md","lastUpdated":1794163917000}`),a={name:`ai/mcp.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to “MCP Server”">​</a></h1><p>本页说明宿主自带的 MCP 端点与开发时可用的 MCP 服务端，适用于把 BasicApp 接入 AI 客户端或用 AI 工具开发 BasicApp 的开发者。</p><p>宿主映射 <code>/mcp</code>：声明了 <code>Expose.Mcp</code> 的操作自动成为 MCP 工具，与 HTTP 接口共用同一份操作契约，认证、租户、权限与审计规则相同。编写代码时，还可以接入框架与 XiHan.UI 的 MCP 服务端查资料。</p><h2 id="basicapp-的-mcp-端点" tabindex="-1">BasicApp 的 MCP 端点 <a class="header-anchor" href="#basicapp-的-mcp-端点" aria-label="Permalink to “BasicApp 的 MCP 端点”">​</a></h2><h3 id="协议" tabindex="-1">协议 <a class="header-anchor" href="#协议" aria-label="Permalink to “协议”">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>端点</td><td><code>POST /mcp</code>（开发时 <code>http://localhost:9710/mcp</code>，前端开发服务器也代理了 <code>/mcp</code>）</td></tr><tr><td>协议</td><td>MCP <code>2025-06-18</code>，JSON-RPC 2.0，Streamable HTTP；一条消息一个答复，不开 SSE、不建会话</td></tr><tr><td>认证</td><td>请求头 <code>Authorization: Bearer &lt;访问令牌&gt;</code>，与 HTTP 接口同一个令牌；凭据无效即 401</td></tr><tr><td>区域</td><td><code>Accept-Language</code> 决定工具标题、说明与错误文案的语言</td></tr><tr><td>服务名</td><td><code>XiHan:Protocols:Mcp:ServerName</code>，缺省 <code>XiHan.BasicApp</code></td></tr></tbody></table><p>每个 <code>tools/call</code> 都是一次独立的内核调用：以令牌的主体与租户执行，经过权限判定、数据范围、字段安全与审计，和前端点按钮没有区别。</p><h3 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to “工具”">​</a></h3><p>工具名由操作 ID 推导：<code>&lt;资源&gt;_&lt;动词&gt;</code>（资源段里的连字符保留，如 <code>dict-items_list</code>），可用 <code>XiHan:Protocols:Mcp:Tools:&lt;操作 ID&gt;</code> 覆盖。发布的都是只读操作：</p><table tabindex="0"><thead><tr><th>工具</th><th>操作</th><th>权限</th></tr></thead><tbody><tr><td><code>users_get</code> / <code>users_list</code></td><td><code>users.get</code> / <code>users.list</code></td><td><code>identity.users.read</code></td></tr><tr><td><code>departments_get</code> / <code>departments_tree</code></td><td><code>departments.get</code> / <code>departments.tree</code></td><td><code>organization.departments.read</code></td></tr><tr><td><code>positions_get</code> / <code>positions_list</code></td><td><code>positions.get</code> / <code>positions.list</code></td><td><code>organization.positions.read</code></td></tr><tr><td><code>memberships_list</code></td><td><code>memberships.list</code></td><td><code>organization.memberships.read</code></td></tr><tr><td><code>permissions_list</code></td><td><code>permissions.list</code></td><td><code>access.permissions.read</code></td></tr><tr><td><code>dicts_get</code> / <code>dicts_list</code> / <code>dicts_options</code></td><td><code>dicts.get</code> / <code>dicts.list</code> / <code>dicts.options</code></td><td><code>settings.dicts.read</code> / 登录即可</td></tr><tr><td><code>dict-items_list</code> / <code>dict-items_tree</code></td><td><code>dict-items.list</code> / <code>dict-items.tree</code></td><td><code>settings.dict-items.read</code></td></tr><tr><td><code>tasks_list</code></td><td><code>tasks.list</code>（我的待办，受理人锁定为调用方）</td><td>登录即可；Workflow 模块开着时</td></tr><tr><td><code>knowledge-documents_search</code></td><td><code>knowledge-documents.search</code>（只在调用方一侧检索）</td><td><code>ai.knowledge-documents.execute</code>；AI 模块开着时</td></tr></tbody></table><ul><li><code>inputSchema</code> / <code>outputSchema</code> 就是操作的请求 / 响应 Schema；</li><li><code>title</code> / <code>description</code> 是操作的本地化文案；</li><li>只读工具带 <code>readOnlyHint</code>；</li><li>失败的调用返回 <code>isError: true</code>，文本是 <code>错误码: 文案</code>。</li></ul><p>管理类写操作不发布到 MCP。新增 MCP 工具：操作必须只读（<code>get</code> / <code>list</code> 或声明 <code>ReadOnly = true</code>），在 <code>Expose</code> 里加 <code>Expose.Mcp | Expose.Ai</code>，并登记到架构测试 <code>OperationExposureTests</code>。</p><h3 id="接入客户端" tabindex="-1">接入客户端 <a class="header-anchor" href="#接入客户端" aria-label="Permalink to “接入客户端”">​</a></h3><p>以 Claude Code 为例，在项目根的 <code>.mcp.json</code>：</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;xihan-basicapp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:9710/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer &lt;访问令牌&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>访问令牌用 <code>auth.login</code> 取得（缺省 120 分钟有效）。令牌代表一个真实用户：给 AI 用的账号按最小权限授予，并留意工具调用同样进访问日志。</p><h3 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to “调试”">​</a></h3><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9710/mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer &lt;访问令牌&gt;&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;jsonrpc&quot;:&quot;2.0&quot;,&quot;id&quot;:1,&quot;method&quot;:&quot;tools/list&quot;}&#39;</span></span></code></pre></div><h2 id="开发用的-mcp-服务端" tabindex="-1">开发用的 MCP 服务端 <a class="header-anchor" href="#开发用的-mcp-服务端" aria-label="Permalink to “开发用的 MCP 服务端”">​</a></h2><table tabindex="0"><thead><tr><th>服务端</th><th>用途</th><th>接入</th></tr></thead><tbody><tr><td><code>xihan-framework</code>（<code>XiHan.Framework.Cli</code> 的 <code>mcp</code> 命令）</td><td>以 stdio 提供框架的离线知识库：包与特性清单、配置键与缺省值、文档检索</td><td>见<a href="https://framework.docs.xihanfun.com/ai/mcp" target="_blank" rel="noreferrer">框架文档的 MCP Server</a>；后端以源码引用锁定提交，对照时以同级检出的 <code>framework/src</code> 为准</td></tr><tr><td><code>xihan-ui</code>（npm <code>@xihan-ui/cli</code>）</td><td>组件 API、部件、示例与设计令牌</td><td>见 <a href="https://ui.docs.xihanfun.com/ai/mcp" target="_blank" rel="noreferrer">XiHan.UI 的 MCP Server</a>；版本取 <code>frontend/pnpm-workspace.yaml</code> catalog 里的 <code>@xihan-ui/vue</code></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./agents">For Agents</a> · <a href="./llms">LLMs.txt</a> · <a href="./../backend/ai">AI 能力</a></li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};